function localDay(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function setData(t,a,complete=false){const key=topicStore(t),old=model[key]||{};if(t.repeat){const entries=[...(old.entries||[])];const i=entries.findIndex(e=>e.id===entryId);const rec={...(i<0?{}:entries[i]),id:entryId,answers:a,updatedAt:new Date().toISOString(),updatedLocalDate:localDay(),complete};if(medContext){rec.links=[...new Set([...(rec.links||[]),medContext])];}if(i<0)entries.push(rec);else entries[i]=rec;model[key]={...old,entries};}else model[key]={...old,answers:a,updatedAt:new Date().toISOString(),updatedLocalDate:localDay(),...(t.id==='basic' && a.weight && a.weight!==old.answers?.weight ? {weightRecordedDate:localDay()} : {}),complete};}
