function goalContext(t,q){
 if(!t)return '';
 if(t.id==='basic')return say('TEMEL BİLGİLER','BASIC INFORMATION');
 if(t.id==='purpose')return say('KULLANIM HEDEFLERİ','TRACKING GOALS');
 const subject=medContext||t.id;
 const parent=topics.find(section=>section.id===subject||section.children?.some(child=>child.id===subject));
 if(!parent)return '';
 const chosen=selectedGoals();
 const matches=chosen.filter(goal=>{
   if(!flowMap[goal]?.includes(parent.id))return false;
   if(parent.id==='conditions'&&subject==='diabetes'&&goal==='bloodPressure')return false;
   if(parent.id==='conditions'&&subject==='hypertension'&&goal==='glucose')return false;
   if(parent.id==='restrictions'&&q){if(q.id==='glucoseGoal'&&goal!=='glucose')return false;if(q.id==='exerciseTarget'&&!['activity','sport'].includes(goal))return false;if(!['glucoseGoal','exerciseTarget'].includes(q.id)&&goal!=='food')return false;}
   return true;
 });
 const opts=topics.find(section=>section.id==='purpose').questions[0].options;
 return opts.filter(option=>matches.includes(option[0])).map(option=>option[english()?2:1]).join(' · ');
}
